def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}, trigger in {none, after_insert},
    # channel in {changes, total_main, total_both}.
    # We simulate each candidate and keep those matching all receipts.

    def simulate(put_mode, trig, chan, actions):
        # state: dict key->value for committed main db
        # other db separate committed state
        main = {}
        other = {}
        # transaction buffers: None means no open txn
        tmain = None
        tother = None
        # counters
        changes_main = 0
        total_main = 0
        total_other = 0
        # trigger log count (unread, but affects total_changes)
        trig_count = 0
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if conn == "main":
                    tmain = {}
                else:
                    tother = {}
            elif op == "commit":
                if conn == "main":
                    if tmain is not None:
                        main.update(tmain)
                        tmain = None
                else:
                    if tother is not None:
                        other.update(tother)
                        tother = None
            elif op == "rollback":
                if conn == "main":
                    tmain = None
                else:
                    tother = None
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    db = main if tmain is None else tmain
                    base = main
                else:
                    db = other if tother is None else tother
                    base = other
                # determine if key exists in the effective view
                # For main txn, view is main overlaid with tmain
                if conn == "main" and tmain is not None:
                    exists = key in tmain or key in main
                elif conn == "other" and tother is not None:
                    exists = key in tother or key in other
                else:
                    exists = key in db
                changed = 0
                if put_mode == "ignore":
                    if not exists:
                        db[key] = val
                        changed = 1
                elif put_mode == "replace":
                    db[key] = val
                    changed = 1
                else:  # upsert
                    if exists:
                        # DO UPDATE SET value=excluded.value
                        # if value same, still counts as change? SQLite counts row as changed
                        db[key] = val
                        changed = 1
                    else:
                        db[key] = val
                        changed = 1
                if changed:
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
                    if trig == "after_insert" and not exists:
                        # trigger fires on insert only
                        trig_count += 1
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    db = main if tmain is None else tmain
                else:
                    db = other if tother is None else tother
                if key in db:
                    db[key] = val
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "delete":
                key = act.get("key")
                if conn == "main":
                    db = main if tmain is None else tmain
                else:
                    db = other if tother is None else tother
                if key in db:
                    del db[key]
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
        # committed state: main + other? No, separate connections to same db file.
        # Actually both connections see same database. Committed state is union.
        # But main and other are separate connections to same file, so committed
        # state is shared. Our model: main and other are views of same committed db.
        # We need to merge: committed = main updated with other's committed changes.
        # Since both write to same file, committed state is the combination.
        # Let's redo: single committed dict, but transactions buffer per connection.
        return None

    # The above is getting complex. Let's simplify: single committed database.
    # Each connection has its own transaction buffer.
    def simulate2(put_mode, trig, chan, actions):
        committed = {}
        tmain = None
        tother = None
        changes_main = 0
        total_main = 0
        total_other = 0
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if conn == "main":
                    tmain = {}
                else:
                    tother = {}
            elif op == "commit":
                if conn == "main":
                    if tmain is not None:
                        committed.update(tmain)
                        tmain = None
                else:
                    if tother is not None:
                        committed.update(tother)
                        tother = None
            elif op == "rollback":
                if conn == "main":
                    tmain = None
                else:
                    tother = None
            elif op == "put":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                # effective view: committed overlaid with this connection's buffer
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                changed = 0
                if put_mode == "ignore":
                    if not exists:
                        if buf is not None:
                            buf[key] = val
                        else:
                            committed[key] = val
                        changed = 1
                elif put_mode == "replace":
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                else:  # upsert
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    changed = 1
                if changed:
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
                    if trig == "after_insert" and not exists:
                        if conn == "main":
                            total_main += 1
                        else:
                            total_other += 1
            elif op == "update":
                key = act.get("key")
                val = act.get("value")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        buf[key] = val
                    else:
                        committed[key] = val
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
            elif op == "delete":
                key = act.get("key")
                if conn == "main":
                    buf = tmain
                else:
                    buf = tother
                if buf is not None:
                    exists = key in buf or key in committed
                else:
                    exists = key in committed
                if exists:
                    if buf is not None:
                        if key in buf:
                            del buf[key]
                        else:
                            # delete from committed inside txn: need tombstone
                            # simplify: mark as deleted in buffer
                            buf[key] = None
                    else:
                        del committed[key]
                    if conn == "main":
                        changes_main = 1
                        total_main += 1
                    else:
                        total_other += 1
        # final committed state: apply buffers? No, uncommitted not visible.
        # committed dict already has committed changes.
        # But tombstones in buffer not applied. For committed state, ignore buffers.
        # However, committed dict may have been modified directly for non-txn.
        # For txn, committed dict only updated on commit.
        # But we used committed dict for non-txn writes directly. Good.
